# פרק 1 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=1
TITLE='תכליות דיני הנזיקין'
SUM=[' <p>דיני הנזיקין עוסקים בשאלה מתי מי שגרם נזק לזולתו חייב לפצותו. המקור המרכזי הוא <strong>פקודת הנזיקין [נוסח חדש]</strong>.</p> <h3>1.1 מבנה הפקודה</h3> <p>שתי קטגוריות: <strong>עוולות מסגרת</strong> רחבות — <strong>רשלנות</strong> (סעיפים 35–36) ו<strong>הפרת חובה חקוקה</strong> (סעיף 63); ו<strong>עוולות פרטיקולריות</strong> ספציפיות — תקיפה, כליאת שווא, הסגת גבול, מטרד ועוד (לשון הרע מוסדרת בחוק נפרד).</p> <h3>1.2 ארבע תכליות מרכזיות</h3> <p><strong>פיצוי</strong> (השבת המצב לקדמותו); <strong>הרתעה</strong> (תמרוץ לנקיטת אמצעי מניעה יעילים); <strong>צדק מתקן</strong> (המזיק שפגע שלא כדין מתקן את העוול); ו<strong>פיזור הנזק</strong> (העברת הנטל לגורם המיטיב לשאתו ולבטחו — מבטח, יצרן).</p> <h3>1.3 יסודות כלליים לאחריות</h3> <p>ככלל נדרשים שלושה: <strong>עוולה</strong> (התנהגות אסורה), <strong>נזק</strong>, ו<strong>קשר סיבתי</strong> ביניהם (<strong>סעיף 64</strong> — "אשם"). בלעדיהם אין חבות.</p> <h3>1.4 נקודות מפתח למבחן</h3> <ul><li>עוולות מסגרת (רשלנות 35–36; חובה חקוקה 63) מול פרטיקולריות.</li><li>ארבע תכליות: פיצוי, הרתעה, צדק מתקן, פיזור נזק.</li><li>שלושה יסודות: עוולה, נזק, קשר סיבתי (ס׳ 64).</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('פקודת הנזיקין [נוסח חדש], התשכ"ח-1968', '', 'המקור המרכזי לדיני הנזיקין — עוולות מסגרת (רשלנות ס׳ 35-36, הפרת חובה חקוקה ס׳ 63) ועוולות פרטיקולריות.'), ("ס' 64 — אשם וקשר סיבתי", '', 'אחריות מותנית בכך שהנזק נגרם באשמו של המזיק — קשר סיבתי בין העוולה לנזק.'), ('תכליות דיני הנזיקין', '', 'פיצוי, הרתעה, צדק מתקן ופיזור נזק — המצדיקות את הטלת האחריות וקובעות את היקפה.'), ('ע״א 10064/02 ״מגדל״ חברה לביטוח בע״מ נ׳ אבו חנא, פ״ד ס(3) 13 (2005)', 'נדונה הערכת אובדן כושר ההשתכרות של קטינה שנפגעה, ובפרט השאלה אם לחשב אותו לפי השכר הממוצע במגזר שאליו היא שייכת או לפי השכר הממוצע במשק כולו.', 'השופט ריבלין קבע שעקרון השבת המצב לקדמותו מבוסס על הצדק המתקן, ושהמכריע הוא נזקו של הניזוק ולא התנהגות המזיק או יכולתו. אובדן ההשתכרות של קטין יחושב לפי השכר הממוצע במשק כולו, ולא לפי נתונים מגזריים, כדי לא להנציח אי־שוויון. ההלכה הוחלה בהמשך גם בכיוון ההפוך (ע״א 9980/06 עיזבון אטינגר נ׳ עיריית ירושלים, 2009).'), ('ע״א 140/00 עיזבון אטינגר נ׳ החברה לשיקום ופיתוח הרובע היהודי בעיר העתיקה בירושלים בע״מ, פ״ד נח(4) 486 (2004)', 'נער כבן 12 נפל לבור באתר משחקים ברובע היהודי ונפטר. נקבע שהחברה התרשלה, ונדונו היקף הפיצוי לעיזבון ובקשה לפיצויים עונשיים.', 'הוכרה לראשונה זכות הניזוק (ועיזבונו) לפיצוי על אובדן ההשתכרות בשנים האבודות, ביטוי מובהק לעקרון ההשבה המלאה. לגבי פיצויים עונשיים ביהמ״ש לא התערב בקביעה שלא לפסוק אותם, משום שמדובר ברשלנות ולא בכוונה או זדון, גם כשהתוצאה טרגית.'), ('ע״א 9656/03 עזבון המנוחה ברטה מרציאנו ז״ל נ׳ ד״ר יורם זינגר (14.1.2005)', 'מטופלת נפטרה ממחלה שהתגלתה באיחור, לאחר שלא בוצעו בדיקות נדרשות. נקבע שהרופאים התרשלו, והעיזבון ביקש גם פיצויים עונשיים.', 'נקבע שהרציונל של פיצויים עונשיים הוא עונש והרתעה, וזה אינו המטרה הרגילה של המשפט האזרחי. לכן הם מוצדקים רק במקרים חמורים, מקוממים ומעוררי סלידה, ובעיקר כשיש כוונה. ברשלנות אין ככלל מקום לפסוק אותם.'), ('ע״א 1338/97 תנובה מרכז שיתופי לשיווק תוצרת חקלאית בישראל בע״מ נ׳ ראבי, פ״ד נז(4) 673 (2003)', 'תובענה בשם צרכנים שצרכו מוצר מזון שלא מדעת, כלומר בלי שקיבלו מידע נכון על המוצר.', 'ביהמ״ש הכיר באפשרות לפצות על פגיעה באוטונומיה של הצרכן, על התחושה שנשללה ממנו הבחירה המודעת מה להכניס לגופו, בהמשך להלכת דעקה בתחום הרפואי. זו דוגמה לכך שדיני הנזיקין מגנים גם על ערכים לא ממוניים, בהשראת חוק יסוד: כבוד האדם וחירותו.'), ('ע״א 11152/04 פלוני נ׳ מגדל חברה לביטוח בע״מ, פ״ד סא(3) 310 (2006)', 'נפגע שבעקבות נזק גוף איבד את היכולת לקיים זוגיות רגילה תבע את עלות שירותי ליווי כחלק מהשבת מצבו לקדמותו.', 'השופט ריבלין קבע ששיקולי טובת הכלל גוברים במקרה זה על השבה מלאה של המצב לקדמותו, בשל התופעות השליליות שנלוות לשירותים אלה. במקום החזר העלות נפסק פיצוי לא ממוני על האובדן. זו דוגמה למתח בין תכליות שונות של דיני הנזיקין.'), ('ע״א 243/83 עיריית ירושלים נ׳ גורדון, פ״ד לט(1) 113 (1985)', 'תביעה נגד עירייה בגין נזק לא גופני שנגרם לתובע מהתנהלות רשלנית שלה, בנסיבות שלא עמדו ביסודות עוולת הנגישה, משום שחסר בהן זדון.', 'נקבע שהעוולות אינן "איים" נפרדים, ושהיעדר יסוד של עוולה פרטיקולרית לא שולל תביעה בעוולת המסגרת של רשלנות. עוד נקבע ש"נזק" לפי ס׳ 2 כולל גם סבל נפשי ופחד בלי ביטוי פיזי. זה ממחיש את הגמישות שעוולות המסגרת מעניקות לבתי המשפט.')]
QS=[{'q': 'מהו העיקרון המרכזי של דיני הפיצויים בנזיקין?', 'o': ['השבת המצב לקדמותו, ככל שכסף מסוגל', 'פיצוי לפי יכולתו הכלכלית של המזיק', 'חלוקת הנזק שווה בשווה בין המזיק לניזוק', 'הענשת המזיק בהתאם לחומרת אשמו'], 'c': 0, 'e': 'נכון. המטרה היא להעמיד את הנפגע במצב שבו היה אילולא העוולה. העיקרון פועל לשני הכיוונים: לא פחות מהנזק ולא יותר ממנו.'}, {'q': 'לפי גישת הצדק המתקן, מה מצדיק את חובתו של המזיק לפצות?', 'o': ['הצורך להרתיע מזיקים פוטנציאליים בעתיד', 'הצורך לצמצם את סך עלויות התאונות בחברה', 'העובדה שהמזיק מבוטח ויכול לפזר את הנזק', 'העובדה שהמזיק הפר שלא כדין את האיזון בינו לבין הנפגע, ועליו לתקן את מה שקלקל'], 'c': 3, 'e': 'נכון. הצדק המתקן רואה ביחסים בין המזיק לניזוק יחסים דו־צדדיים, והפיצוי מתקן את הפגיעה שהמזיק גרם בהתנהגות פסולה.'}, {'q': 'מה הרעיון של קלברזי, "מונע הנזק הזול"?', 'o': ['יש להטיל אחריות על מי שאשם מוסרית יותר', 'יש לפטור מאחריות כל מי שהשקיע באמצעי זהירות כלשהם', 'יש להטיל את האחריות על מי שיכול למנוע את הנזק בעלות הנמוכה ביותר, גם אם זה הניזוק', 'יש להטיל אחריות רק על גופים עשירים'], 'c': 2, 'e': 'נכון. לפי הגישה הזאת, הטלת האחריות על מי שמונע את הנזק בזול ביותר מביאה למזעור עלויות התאונות.'}, {'q': 'מהי "הרתעת יתר" ולמה היא בעיה?', 'o': ['מצב שבו אחריות רחבה מדי גורמת להימנעות מפעילות רצויה או לזהירות מופרזת ובזבזנית', 'מצב שבו המזיק משלם פחות מהנזק שגרם', 'מצב שבו המזיק נענש פעמיים, בפלילים ובנזיקין', 'מצב שבו הנפגע מקבל פיצוי גם מהמבטח וגם מהמזיק'], 'c': 0, 'e': 'נכון. למשל "רפואה מתגוננת" או רשויות שנמנעות מפעולה מחשש לתביעות. זה טיעון מרכזי נגד הרחבת אחריות, במיוחד של רשויות ציבוריות.'}, {'q': 'איזו תכלית מסבירה בעיקר את הסדר האין־אשם בחוק הפיצויים לנפגעי תאונות דרכים?', 'o': ['ענישת נהגים רשלנים', 'צדק מתקן', 'צדק חלוקתי ופיזור הנזק באמצעות ביטוח חובה', 'הגנה על חופש הפעולה של הנהג'], 'c': 2, 'e': 'נכון. הנזק מפוזר על כלל המבוטחים, והנפגע מקבל פיצוי בלי להוכיח אשם (שיעור 15).'}, {'q': 'מה ההבדל בין פיצויים מוגברים לפיצויים עונשיים?', 'o': ['פיצויים מוגברים מפצים על נזק לא ממוני שהוחמר בגלל התנהגות המזיק, ואילו פיצויים עונשיים חורגים מהנזק כדי להעניש', 'פיצויים מוגברים נפסקים רק בהליך פלילי', 'פיצויים עונשיים ניתנים רק ברשלנות, ומוגברים רק בכוונה', 'אין הבדל, אלה שני שמות לאותו דבר'], 'c': 0, 'e': 'נכון. הפיצוי המוגבר עדיין משקף נזק (סבל שהוחמר). הפיצוי העונשי הוא תוספת מעבר לנזק, שנועדה לגנות ולהרתיע.'}, {'q': 'דנה תבעה את שכנה בגין "גרימת נזק" כללית, בלי להצביע על עוולה מסוימת. בית המשפט שאל אותה על איזו עוולה היא מבססת את התביעה. למה?', 'o': ['כי נזק בין שכנים מוסדר רק בדיני החוזים', 'כי צריך להוכיח קודם הרשעה פלילית', 'כי ס׳ 3 לפקודה קובע שהעוולות הן "הדברים המנויים", כלומר רשימה סגורה', 'כי בישראל אין תביעות נזיקין בין שכנים'], 'c': 2, 'e': 'נכון. אין עוולה כללית של גרימת נזק, וצריך לעגן את התביעה בעוולה מוכרת. ברוב המקרים ניתן לעשות זאת ברשלנות או בהפרת חובה חקוקה.'}, {'q': 'משה נפגע בתאונה וקיבל 80,000 ש״ח מביטוח תאונות אישיות שרכש בעצמו. המזיק מבקש לנכות את הסכום מהפיצוי. מה הדין?', 'o': ['הסכום ינוכה בחצי, כפשרה בין הצדדים', 'הסכום לא ינוכה, לפי ס׳ 86 לפקודה', 'הסכום ינוכה רק אם המזיק היה רשלן בדרגה נמוכה', 'הסכום ינוכה במלואו, אחרת משה יקבל פיצוי כפול'], 'c': 1, 'e': 'נכון. ס׳ 86 קובע שלא יובא בחשבון סכום ששולם לפי חוזה ביטוח. כך נשמרות ההרתעה והאחריות האישית של המזיק.'}, {'q': 'נגד אדם שתקף את שכנו מתנהל משפט פלילי. השכן הגיש באותו זמן תביעה נזיקית על התקיפה. התוקף טוען שאין לדון בתביעה כל עוד ההליך הפלילי תלוי ועומד. מה הדין?', 'o': ['התביעה תידחה עד סיום ההליך הפלילי', 'העבירה אינה מחסום לתביעה. אם העובדות עשויות להוות פשע, ביהמ״ש רק מוודא שהן ידועות למשטרה', 'בית המשפט האזרחי חייב להעביר את התיק לבית המשפט הפלילי', 'התביעה אפשרית רק אם התוקף יורשע'], 'c': 1, 'e': 'נכון. זה לשון ס׳ 88. במקרה של פשע ביהמ״ש מעכב את ההליך עד שהוא נוכח שהעובדות נמסרו למשטרה או ידועות לה, והתקיפה עצמה היא גם עוולה לפי ס׳ 23.'}, {'q': 'עובד במשרד ממשלתי טעה ברשלנות בטיפול בבקשה, ונגרם לאזרח נזק. האזרח מבקש לתבוע אישית את העובד. מה הדין העקרוני?', 'o': ['העובד נהנה מחסינות לפי ס׳ 7א, והתביעה תופנה למדינה, אלא אם פעל ביודעין בכוונה להזיק או בשוויון נפש', 'העובד חב רק אם הנזק עולה על סכום מסוים', 'גם העובד וגם המדינה חסינים תמיד בפעולות שלטוניות', 'העובד חב אישית תמיד, כי הוא שגרם את הנזק'], 'c': 0, 'e': 'נכון. ס׳ 7א מעניק חסינות לעובד ציבור שפעל במילוי תפקידו השלטוני. אחריות המדינה נשמרת, ובכך מושגים פיצוי לנפגע ומניעת הרתעת יתר של העובד.'}, {'q': 'אדם דחף בטעות אדם אחר בתור לקופה, בלי שום נזק. הנדחף רוצה לתבוע. איזו הגנה בפקודה עשויה לעמוד לדוחף?', 'o': ['חסינות שיפוטית (ס׳ 8)', 'מעשה של מה בכך (ס׳ 4)', 'הסתכנות מרצון (ס׳ 5)', 'מעשה לפי חיקוק (ס׳ 6)'], 'c': 1, 'e': 'נכון. אם אדם בר־דעת ומזג רגיל לא היה מתלונן על כך, וחזרה על המעשה לא הייתה יוצרת זכות נוגדת, זה "מעשה של מה בכך" ואינו עוולה.'}, {'q': 'בית משפט שקל לפסוק פיצויים עונשיים נגד רופא שהתרשל ברשלנות חמורה, ללא כוונה. לפי הפסיקה, מה הסיכוי?', 'o': ['גבוה, כי הרשלנות הייתה חמורה', 'גבוה, אם הנזק גדול', 'נמוך מאוד, כי פיצויים עונשיים נפסקים בעיקר כשיש כוונה או זדון, ולא ברשלנות גם אם היא חמורה', 'אפסי, כי בישראל אין בכלל פיצויים עונשיים'], 'c': 2, 'e': 'נכון. הפסיקה דורשת התנהגות מקוממת, ובעיקר כוונה או זדון, ומטעם זה נמנעה מפסיקת פיצויים עונשיים בעוולות רשלנות.'}, {'q': 'ילדה בת 8 מכפר שבו השכר הממוצע נמוך נפגעה בתאונה ואיבדה את כושר ההשתכרות. לפי איזה שכר יחושב הפיצוי בגין אובדן ההשתכרות העתידי?', 'o': ['לפי השכר הממוצע במשק כולו', 'לפי השכר הממוצע במגזר שלה בתוספת קטנה', 'לפי שכר המינימום', 'לפי השכר הממוצע בכפר שלה'], 'c': 0, 'e': 'נכון. לפי הלכת אבו חנא, כושר ההשתכרות של קטין מחושב לפי השכר הממוצע במשק כולו. ההלכה הוחלה גם בכיוון ההפוך.'}, {'q': 'חברה גדולה פגעה בצרכן. נטען שיש להטיל עליה אחריות "כי היא יכולה לגלגל את העלות למחיר המוצר". לאיזו תכלית שייך הטיעון?', 'o': ['צדק מתקן', 'פיזור נזקים וצדק חלוקתי', 'הגנה על האוטונומיה', 'ענישה'], 'c': 1, 'e': 'נכון. יכולת לפזר את עלות הנזק על ציבור גדול, דרך מחירים, פרמיות או מסים, היא לב הטיעון של "המפזר הטוב".'}, {'q': 'מה נקבע בעניין דעקה נ׳ בית החולים כרמל לעניין תכליות דיני הנזיקין?', 'o': ['שרופא לא חב בנזיקין כלפי מטופלו', 'שטיפול רפואי ללא הסכמה מדעת מזכה רק בפיצויים עונשיים', 'שיש לפצות על פגיעה באוטונומיה, בזכות להחליט על הגוף, כראש נזק עצמאי, גם בלי להוכיח שהמטופל היה מסרב לטיפול', 'שאין לפצות על נזק לא ממוני'], 'c': 2, 'e': 'נכון. בדעקה הוכר לראשונה, ברוב דעות, פיצוי על פגיעה באוטונומיה, בהשראת חוק יסוד: כבוד האדם וחירותו.'}, {'q': 'מה נקבע בעניין פלוני נ׳ מגדל (2006) לגבי תביעה לעלות שירותי ליווי?', 'o': ['ששיקולי טובת הכלל גוברים במקרה זה על השבה מלאה, ולכן נפסק פיצוי לא ממוני על האובדן במקום העלות', 'שיש לפסוק את מלוא העלות לפי עקרון ההשבה', 'שיש לפסוק פיצויים עונשיים נגד המבטחת', 'שהתביעה נדחתה כולה כי אין נזק'], 'c': 0, 'e': 'נכון. השופט ריבלין העדיף את טובת הכלל על החזר מלא של העלות. זו דוגמה למתח בין התכליות.'}, {'q': 'מה קבע ביהמ״ש בעניין עיריית ירושלים נ׳ גורדון לגבי היחס בין העוולות?', 'o': ['שרשלנות חלה רק על נזקי גוף', 'שמי שלא עומד ביסודות עוולה פרטיקולרית מנוע מלתבוע ברשלנות', 'שהעוולות אינן "איים" נפרדים, ושאפשר לתבוע ברשלנות גם כשחסר יסוד של עוולה ספציפית', 'שהעירייה חסינה מתביעות נזיקין'], 'c': 2, 'e': 'נכון. עוולות המסגרת יכולות לחפוף לעוולות הפרטיקולריות. בגורדון גם הובהר שנזק כולל סבל נפשי בלי ביטוי פיזי.'}, {'q': 'מה ההבחנה בין אחריות חמורה לאחריות מוחלטת?', 'o': ['אחריות מוחלטת חלה רק על המדינה', 'אין הבחנה, אלה שמות נרדפים', 'באחריות חמורה צריך להוכיח כוונה, ובמוחלטת רשלנות', 'בשתיהן אין צורך באשם, אבל באחריות חמורה יש לנתבע הגנות מסוימות, ובמוחלטת כמעט אין'], 'c': 3, 'e': 'נכון. למשל, חוק האחריות למוצרים פגומים (אחריות חמורה, עם הגנות), מול חוק הפיצויים לנפגעי תאונות דרכים (קרוב לאחריות מוחלטת).'}, {'q': 'לפי לשון ס׳ 2 לפקודת הנזיקין, מה כולל המונח "נזק"?', 'o': ['רק אבדן חיים ואבדן נכס', 'אבדן חיים, אבדן נכס, נוחות, רווחה גופנית או שם טוב, או חיסור מהם, וכל אבדן או חיסור כיוצאים באלה', 'רק נזק שנגרם בכוונה', 'רק נזק ממוני שניתן לכמת בכסף'], 'c': 1, 'e': 'נכון. זו לשון ההגדרה, והסיפא הפתוחה ("כיוצאים באלה") מאפשרת להכיר בסוגי נזק חדשים.'}, {'q': 'לפי ס׳ 3 לפקודת הנזיקין, ממי זכאי הנפגע מעוולה לתרופה?', 'o': ['רק מחברת הביטוח של המזיק', 'מידי עושה העוולה או האחראי לה', 'רק מהמדינה', 'רק ממי שהורשע בפלילים'], 'c': 1, 'e': 'נכון. הלשון "עושה העוולה או האחראי לה" מאפשרת גם אחריות למעשי אחרים, כמו אחריות שילוחית של מעביד.'}, {'q': 'מהו המקור המרכזי של דיני הנזיקין?', 'o': ['חוק החוזים', 'פקודת הנזיקין', 'חוק העונשין', 'חוק יסוד'], 'c': 1, 'e': 'פקודת הנזיקין [נוסח חדש] 1968.'}, {'q': 'רשלנות והפרת חובה חקוקה הן:', 'o': ['עוולות פרטיקולריות', 'עוולות מסגרת', 'חוזים', 'עבירות'], 'c': 1, 'e': 'עוולות מסגרת רחבות.'}, {'q': 'איזו אינה תכלית של דיני הנזיקין?', 'o': ['פיצוי', 'הרתעה', 'ענישה פלילית', 'פיזור נזק'], 'c': 2, 'e': 'הענישה היא תכלית פלילית.'}, {'q': '"צדק מתקן" עניינו:', 'o': ['חלוקה שוויונית', 'תיקון העוול בין המזיק לניזוק', 'הרתעה', 'ביטוח'], 'c': 1, 'e': 'המזיק מתקן את שגרם.'}, {'q': 'מהם שלושת היסודות הכלליים לאחריות?', 'o': ['חוזה/הפרה/נזק', 'עוולה/נזק/קשר סיבתי', 'כוונה/מעשה/תוצאה', 'חובה/זכות/סעד'], 'c': 1, 'e': 'הבסיס לחבות.'}]
MAR=[]
